UPDATE geo_entities SET confidence_score = 0.72, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS-007: la violenza imperiale e'' documentata dalle iscrizioni reali STESSE (propaganda celebrativa, non cronaca neutrale): Rimush (figlio di Sargon) rivendica 56.041 uccisi e 29.438 ridotti in schiavitu'' nella repressione delle rivolte delle citta'' sumere; Naram-Sin vittorie in nove battaglie in un anno. Documentano l''ideologia di conquista e la deportazione/schiavizzazione di massa. La capitale Agade non e'' ancora stata localizzata. Aggiunte fonti (Frayne RIME 2 per le iscrizioni, Liverani, Van De Mieroop, Kuhrt); confidence 0.55->0.72.' END WHERE id = 169;

-- id=173 Umayyad (conf->0.75)
UPDATE geo_entities SET confidence_score = 0.75, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS-009: i mawali (convertiti non-arabi) continuarono a pagare la jizya nonostante la conversione all''Islam — una gerarchia etnica istituzionalizzata che privilegiava gli arabi; Umar II la aboli'' brevemente, Yazid II la reimpose. La Rivolta Berbera (739-740) insorse contro questo trattamento discriminatorio dei musulmani nordafricani. Le riforme di Abd al-Malik (697-706) sostituirono greco/persiano/copto con l''arabo nell''amministrazione (arabizzazione). Le conquiste (al-Andalus, Sind, Transoxiana) produssero riduzione in schiavitu'' di massa dei prigionieri. Aggiunte fonti (Robinson, Blankinship, Crone, Donner); confidence 0.40->0.75.' END WHERE id = 173;

-- id=111 Maratha (conf->0.75)
UPDATE geo_entities SET confidence_score = 0.75, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS-002/007: l''espansione Maratha si finanzio'' col chauth (~25% del gettito) e il sardeshmukhi (~10% aggiuntivo), tributi spesso estratti con incursioni militari. La Terza Battaglia di Panipat (1761) costo'' ~60-70.000 morti in combattimento; secondo la cronaca oculare di Kashi Raja ~40.000 prigionieri Maratha furono massacrati il giorno dopo; Shejwalkar stima ~100.000 morti Maratha tra combattenti e civili. Aggiunte fonti (Gordon Cambridge, Sardesai, Shejwalkar, Pearson); confidence 0.40->0.75.' END WHERE id = 111;

-- id=342 Ghurid (conf->0.7)
UPDATE geo_entities SET confidence_score = 0.7, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS-007: le campagne di Muhammad of Ghor in India (vittoria a Tarain 1192 su Prithviraj Chauhan) includono, secondo le cronache islamiche stesse (Ibn al-Athir, al-Kamil), distruzione di templi indu'' ad Ajmer sostituiti da moschee, massacri e riduzione in schiavitu'' di donne vendute nel mondo islamico. Dal generale-schiavo Qutb al-Din Aibak nacque il Sultanato di Delhi. Queste fonti sono medievali e celebrative: documentano l''iconoclastia e la schiavizzazione come vanto, non come neutra cronaca. Aggiunte fonti (Jackson, Wink, Flood); confidence 0.40->0.70.' END WHERE id = 342;

-- id=491 Zagwe (conf->0.65)
UPDATE geo_entities SET confidence_score = 0.65, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS-008: la dinastia Zagwe (Agaw, cushitica) fu delegittimata come ''usurpatrice'' dalla successiva dinastia Salomonide (dal 1270), che fece redigere il Kebra Nagast (~40 anni dopo) per rivendicare una discendenza salomonica ''restaurata'' contro i ''pretendenti'' Zagwe — una cancellazione narrativa di una dinastia di fatto legittima. Costrui'' le chiese rupestri di Lalibela. La documentazione resta scarsa (Derat la chiama ''l''enigma''): confidence tenuta a 0.65 per onesta'' sull''incertezza. Aggiunte fonti (Derat Brepols 2018, Phillipson, Tamrat); confidence 0.40->0.65.' END WHERE id = 491;

-- id=490 Neo-Babylon (conf->0.78)
UPDATE geo_entities SET confidence_score = 0.78, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS-007: nel 587 a.C. Nabucodonosor II distrusse Gerusalemme e rase al suolo il Tempio di Salomone, deportando in piu'' ondate (597 ~7.000; 587 e oltre) gran parte della popolazione del Regno di Giuda in Babilonia — la ''cattivita'' babilonese'', deportazione forzata di un intero popolo, non una semplice annessione. Aggiunte fonti (Beaulieu, Wiseman, Vanderhooft); confidence 0.55->0.78.' END WHERE id = 490;

-- id=274 Mycenae (conf->0.7)
UPDATE geo_entities SET confidence_score = 0.7, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS: i testi in Lineare B documentano lavoro servile/dipendente (''do-e-ro'', schiavi del palazzo o delle divinita''), benche'' non risultino registri di compravendita di persone — una dipendenza diversa dalla schiavitu''-merce greca classica. La struttura politica e'' ricostruita archeologicamente (confidence 0.70). La civilta'' palaziale micenea collasso'' nel Bronze Age collapse (~1177 a.C.). Aggiunte fonti (Chadwick, Dickinson, Shelmerdine, Cline); confidence 0.55->0.70.' END WHERE id = 274;

-- id=188 Saba (conf->0.68)
UPDATE geo_entities SET confidence_score = 0.68, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS: la Regina di Saba e'' leggenda — nessuna iscrizione sabea la attesta; il regno fiori'' dall''VIII sec. a.C., ~due secoli dopo l''epoca tradizionale di Salomone (Finkelstein/Silberman). Il regno storico e'' documentato da epigrafia sabea, dalla diga di Marib e dal controllo del commercio dell''incenso. La leggenda riflette interazioni storiche reali filtrate da agende teologiche posteriori. Aggiunte fonti (Hoyland, Korotayev, Simpson/British Museum); confidence 0.50->0.68.' END WHERE id = 188;

