-- id=146 Wagadou/Ghana (conf->0.68)
UPDATE geo_entities SET confidence_score = 0.68, status = 'confirmed', ethical_notes = CASE WHEN ethical_notes LIKE '%[S51-enrich]%' THEN ethical_notes ELSE COALESCE(ethical_notes, '') || E'\n\n' || '[S51-enrich] ETHICS: la ''conquista almoravide di Ghana (1076)'' e'' un MITO storiografico — Conrad & Fisher (1982) non trovano evidenza ne'' nelle fonti arabe esterne ne'' nella tradizione orale locale; il declino di Wagadou fu graduale e interno, NON una conquista militare. E'' una correzione di una narrazione di origine coloniale. Regno soninke fondato sul commercio transahariano oro-sale (e schiavi). Aggiunte fonti (Levtzion, Levtzion & Hopkins Corpus, Conrad & Fisher); confidence 0.45->0.68.' END WHERE id = 146;

